package hu.synostream.android;
import org.junit.Test;import static org.junit.Assert.*;import org.json.*;import java.util.*;import java.io.*;import java.nio.charset.StandardCharsets;import java.util.concurrent.atomic.*;
public class LibraryIncrementalTest {
 static final long NOW=100L*24*60*60*1000;
 static final class Files implements Library.Source {
  final Map<String,List<NasClient.Entry>> folders=new LinkedHashMap<>();final Map<String,byte[]> files=new HashMap<>();int reads,lists;java.util.function.Consumer<String> beforeList=p->{};
  void folder(String path,String... names){List<NasClient.Entry> rows=new ArrayList<>();for(String name:names){boolean dir=name.endsWith("/");if(dir)name=name.substring(0,name.length()-1);NasClient.Entry e=new NasClient.Entry(name,path+"/"+name,dir,0);e.modified=100;rows.add(e);}folders.put(path,rows);}
  void text(String path,String text){files.put(path,text.getBytes(StandardCharsets.UTF_8));String parent=path.substring(0,path.lastIndexOf('/'));List<NasClient.Entry> entries=folders.get(parent);if(entries!=null)for(int i=0;i<entries.size();i++)if(entries.get(i).path.equals(path)){NasClient.Entry old=entries.get(i),e=new NasClient.Entry(old.name,old.path,false,files.get(path).length);e.modified=old.modified;entries.set(i,e);}}
  public List<NasClient.Entry> list(String path)throws Exception{beforeList.accept(path);lists++;if(!folders.containsKey(path))throw new IOException("Fixture folder unavailable");return folders.get(path);}
  public byte[] readFile(String path,int max)throws Exception{reads++;if(!files.containsKey(path))throw new IOException("Fixture file unavailable");return files.get(path).clone();}
 }
 static Library.Card known(String path,long id){Library.Card c=new Library.Card(path,"Cached Hungarian title",true);c.id=id;c.lookupState="matched";c.origin="name";c.modified=100;c.metadataAt=NOW-1000;c.overview="Cached description";c.poster="poster";return c;}
 static JSONObject info(long id,String title)throws Exception{return new JSONObject().put("id",id).put("title",title).put("original_title",title).put("release_date","2020-01-01").put("overview","Description");}
 static Recognition.Api noApi(){return (path,p)->{throw new AssertionError("Unchanged cached metadata must not call the API");};}
 static Recognition.Api api(AtomicInteger searches){return (path,p)->{if(path.startsWith("search/")){searches.incrementAndGet();return new JSONObject().put("results",new JSONArray().put(info(900,p.get("query"))));}if(path.endsWith("alternative_titles"))return new JSONObject();return info(900,"Fresh Movie");};}
 Library library(Files f,Recognition.Api api,List<Library.Card> old){Library l=new Library(f,api);l.previous(old);l.clock(()->NOW);return l;}
 @Test public void oneNewMovieAmongOneThousandMatchesDoesOnlyOneTitleLookup()throws Exception{Files f=new Files();String[] names=new String[1001];List<Library.Card> old=new ArrayList<>();for(int i=0;i<1000;i++){names[i]="Known."+i+".mkv";old.add(known("/movies/"+names[i],10000+i));}names[1000]="Fresh.Movie.2020.mkv";f.folder("/movies",names);AtomicInteger calls=new AtomicInteger();Library l=library(f,api(calls),old);List<Library.Card> found=l.scan("/movies",true,n->{});assertEquals(1001,found.size());assertEquals(2,calls.get());assertEquals(1,f.lists);assertEquals(0,f.reads);assertEquals(1000,found.stream().filter(c->c.id>=10000).count());}
 @Test public void legacyMatchedCacheIsAdoptedWithoutRequeryAndRoundTrips()throws Exception{Files f=new Files();f.folder("/movies","Title.mkv");Library.Card old=known("/movies/Title.mkv",1);old.metadataAt=0;Library.Card result=library(f,noApi(),List.of(old)).scan("/movies",true,n->{}).get(0);assertEquals(NOW,result.metadataAt);Library.Card restored=Library.Card.from(result.json());assertEquals(NOW,restored.metadataAt);assertEquals("Cached Hungarian title",restored.title);assertEquals(0,old.metadataAt);}
 @Test public void unchangedGoodMetadataIsPreservedEvenWithoutApiKey()throws Exception{Files f=new Files();f.folder("/movies","Title.mkv");Library.Card result=library(f,null,List.of(known("/movies/Title.mkv",1))).scan("/movies",true,n->{}).get(0);assertEquals(1,result.id);assertEquals("Cached description",result.overview);}
 @Test public void changedVideoTimestampTriggersRecognition()throws Exception{Files f=new Files();f.folder("/movies","Title.2020.mkv");f.folders.get("/movies").get(0).modified=101;AtomicInteger searches=new AtomicInteger();Library.Card old=known("/movies/Title.2020.mkv",1);Library.Card result=library(f,api(searches),List.of(old)).scan("/movies",true,n->{}).get(0);assertEquals(2,searches.get());assertEquals(900,result.id);assertEquals(1,old.id);}
 @Test public void expiredPositiveAndExplicitFullRefreshDoRequery()throws Exception{for(boolean force:new boolean[]{false,true}){Files f=new Files();f.folder("/movies","Title.2020.mkv");Library.Card old=known("/movies/Title.2020.mkv",1);if(!force)old.metadataAt=NOW-LibraryRefresh.MATCH_AGE-1;AtomicInteger searches=new AtomicInteger();Library l=library(f,api(searches),List.of(old));l.forceMetadata(force);l.scan("/movies",true,n->{});assertEquals(2,searches.get());}}
 @Test public void unchangedNfoSignatureAvoidsBothNfoReadAndApi()throws Exception{Files f=new Files();f.folder("/movies","Title.mkv","Title.nfo");f.text("/movies/Title.nfo","tmdb: 1");Library.Card old=known("/movies/Title.mkv",1);old.origin="nfo";old.nfoPath="/movies/Title.nfo";old.nfoModified=100;old.nfoSize=f.files.get(old.nfoPath).length;library(f,noApi(),List.of(old)).scan("/movies",true,n->{});assertEquals(0,f.reads);}
 @Test public void changedNfoIdOverridesKnownMatch()throws Exception{Files f=new Files();f.folder("/movies","Title.mkv","Title.nfo");f.text("/movies/Title.nfo","https://www.themoviedb.org/movie/2");Library.Card old=known("/movies/Title.mkv",1);old.origin="nfo";old.nfoPath="/movies/Title.nfo";old.nfoModified=99;Library.Card c=library(f,(path,p)->{assertEquals("movie/2",path);return info(2,"Correct NFO title");},List.of(old)).scan("/movies",true,n->{}).get(0);assertEquals(2,c.id);assertEquals(1,f.reads);}
 @Test public void legacyNfoIdCanReuseDetailsAfterReadingTheCurrentFile()throws Exception{Files f=new Files();f.folder("/movies","Title.mkv","Title.nfo");f.text("/movies/Title.nfo","https://www.themoviedb.org/movie/1");Library.Card old=known("/movies/Title.mkv",1);old.origin="nfo";Library.Card c=library(f,noApi(),List.of(old)).scan("/movies",true,n->{}).get(0);assertEquals(1,c.id);assertEquals(1,f.reads);assertEquals("tmdb:1",c.nfoToken);}
 @Test public void removedNfoDoesNotKeepItsOldIdentification()throws Exception{Files f=new Files();f.folder("/movies","Title.2020.mkv");Library.Card old=known("/movies/Title.2020.mkv",1);old.origin="nfo";old.nfoPath="/movies/Title.nfo";AtomicInteger searches=new AtomicInteger();library(f,api(searches),List.of(old)).scan("/movies",true,n->{});assertEquals(2,searches.get());}
 @Test public void recentConfirmedMissIsNotSearchedAgainButExpiryAndRetryAre()throws Exception{for(String state:List.of("no_result","retry","expired")){Files f=new Files();f.folder("/movies","Title.2020.mkv");Library.Card old=known("/movies/Title.2020.mkv",-1);old.lookupState=state.equals("expired")?"no_result":state;if(state.equals("expired"))old.metadataAt=NOW-LibraryRefresh.NO_RESULT_AGE-1;AtomicInteger searches=new AtomicInteger();library(f,api(searches),List.of(old)).scan("/movies",true,n->{});assertEquals(state,state.equals("no_result")?0:2,searches.get());}}
 @Test public void metadataExpiryIsNotExtendedByRepeatedRefreshes()throws Exception{Files f=new Files();f.folder("/movies","Title.mkv");Library.Card old=known("/movies/Title.mkv",1);Library.Card c=library(f,noApi(),List.of(old)).scan("/movies",true,n->{}).get(0);assertEquals(old.metadataAt,c.metadataAt);}
 @Test public void previewsPrecedeAllMetadataAndUseMostRecentFolderFirst()throws Exception{Files f=new Files();f.folder("/movies","Old/","New/");f.folder("/movies/Old","Old.Movie.2020.mkv");f.folder("/movies/New","Fresh.Movie.2020.mkv");f.folders.get("/movies").get(1).modified=200;List<String> seen=new ArrayList<>();AtomicBoolean finished=new AtomicBoolean();Library l=library(f,(path,p)->{assertTrue(finished.get());assertFalse(seen.isEmpty());return api(new AtomicInteger()).get(path,p);},List.of());l.preview(c->{seen.add(c.path);assertTrue(c.id<0||finished.get());},()->finished.set(true));l.scan("/movies",true,n->{});assertEquals("/movies/New/Fresh.Movie.2020.mkv",seen.get(0));assertEquals(3,f.lists);}
 @Test public void newShowPreviewDoesNotWaitForAllExistingSeasonTrees()throws Exception{Files f=new Files();f.folder("/shows","Old.Show/","New.Show/");f.folder("/shows/Old.Show","Season.1/");f.folder("/shows/Old.Show/Season.1","S01E01.mkv");f.folder("/shows/New.Show","S01E01.mkv");Library.Card old=new Library.Card("/shows/Old.Show","Old Show",false);old.episodeRoots.add(old.path);AtomicBoolean finished=new AtomicBoolean(),newSeen=new AtomicBoolean();f.beforeList=p->{if(p.equals("/shows/Old.Show"))assertTrue("Old episode walk belongs after early inventory",finished.get());};Library l=library(f,null,List.of(old));l.preview(c->{if(c.path.equals("/shows/New.Show"))newSeen.set(true);},()->{assertTrue(newSeen.get());finished.set(true);});assertEquals(2,l.scan("/shows",false,n->{}).size());}
 @Test public void unknownNfoTimesAreNeverBlindlyTrusted()throws Exception{Library.Card old=known("/movies/Title.mkv",1),current=new Library.Card(old.path,"Title",true);old.origin="nfo";old.nfoPath="/movies/Title.nfo";old.nfoModified=0;NasClient.Entry nfo=new NasClient.Entry("Title.nfo",old.nfoPath,false,10);nfo.modified=0;assertFalse(LibraryRefresh.unchanged(old,current,nfo,NOW));}
 void pairing(Files f,long id,boolean deleted)throws Exception{String event="00000000000000000000000000000001";f.folder("/movies","Title.2020.mkv",".synostream/");f.folder("/movies/.synostream","parositasok/");f.folder("/movies/.synostream/parositasok",event+".json");JSONObject value=PairingsTest.event(event,"Title.2020.mkv",id,1);if(deleted)value.put("deleted",true).put("tmdb_id",JSONObject.NULL);f.text("/movies/.synostream/parositasok/"+event+".json",value.toString());}
 @Test public void sameManualIdReusesDataButChangedAndDeletedEventsDoNot()throws Exception{for(int mode=0;mode<3;mode++){Files f=new Files();pairing(f,mode==1?45:44,mode==2);Library.Card old=known("/movies/Title.2020.mkv",44);old.origin="manual";AtomicInteger searches=new AtomicInteger();Recognition.Api api=mode==0?noApi():mode==1?(path,p)->{assertEquals("movie/45",path);return info(45,"Updated manual title");}:api(searches);Library.Card result=library(f,api,List.of(old)).scan("/movies",true,n->{}).get(0);assertEquals(mode==0?44:mode==1?45:900,result.id);if(mode==2)assertEquals(2,searches.get());}}
 @Test public void sharedPairingBytesAreReusedOnlyForSameOwnerAndUnchangedStamp()throws Exception{Files f=new Files();pairing(f,44,false);PairingReadCache cache=new PairingReadCache();Library first=library(f,(path,p)->info(44,"Manual title"),List.of());first.pairingCache(cache,"alice");List<Library.Card> result=first.scan("/movies",true,n->{});assertEquals(1,f.reads);Library second=library(f,noApi(),result);second.pairingCache(cache,"alice");second.scan("/movies",true,n->{});assertEquals(1,f.reads);Library other=library(f,noApi(),result);other.pairingCache(cache,"bob");other.scan("/movies",true,n->{});assertEquals(2,f.reads);f.folders.get("/movies/.synostream/parositasok").get(0).modified++;Library changed=library(f,noApi(),result);changed.pairingCache(cache,"alice");changed.scan("/movies",true,n->{});assertEquals(3,f.reads);}

 @Test public void titleOnlySharedManualMatchIsEnrichedWhenAnApiBecomesAvailable()throws Exception{Files f=new Files();pairing(f,44,false);Library.Card old=known("/movies/Title.2020.mkv",44);old.origin="manual";old.metadataAt=0;old.overview="";old.poster="";AtomicInteger details=new AtomicInteger();Library.Card result=library(f,(path,p)->{details.incrementAndGet();assertEquals("movie/44",path);return info(44,"Rich manual title");},List.of(old)).scan("/movies",true,n->{}).get(0);assertEquals(1,details.get());assertEquals("Description",result.overview);assertEquals(NOW,result.metadataAt);}

 @Test public void automaticRefreshKeepsOldConfirmedMetadataWithoutApi()throws Exception{Files f=new Files();f.folder("/movies","Title.mkv");Library.Card old=known("/movies/Title.mkv",1);old.metadataAt=NOW-60L*24*60*60*1000;Library l=library(f,noApi(),List.of(old));l.reuseConfirmed(true);assertEquals(1,l.scan("/movies",true,n->{}).get(0).id);}
}
